#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        printf("USAGE\n");
        return 0;
    }

    char *mode = argv[1];
    char *str = argv[2];

    if (strcmp(mode, "escape") == 0) {
        // escape logic
        int len = strlen(str);
        char *escaped_str = (char *)malloc(len * 2 + 1);
        int j = 0;
        for (int i = 0; i < len; i++) {
            if (str[i] == '\\') {
                escaped_str[j++] = '\';
                escaped_str[j++] = '\';
            } else if (str[i] == '\n') {
                escaped_str[j++] = '\';
                escaped_str[j++] = 'n';
            } else {
                escaped_str[j++] = str[i];
            }
        }
        escaped_str[j] = '\0';
        printf("%s\n", escaped_str);
        free(escaped_str);
    } else if (strcmp(mode, "unescape") == 0) {
        // unescape logic
        int len = strlen(str);
        char *unescaped_str = (char *)malloc(len + 1);
        int j = 0;
        for (int i = 0; i < len; i++) {
            if (str[i] == '\') {
                if (i + 1 < len) {
                    if (str[i + 1] == 'n') {
                        unescaped_str[j++] = '\n';
                        i++;
                    } else if (str[i + 1] == '\') {
                        unescaped_str[j++] = '\';
                        i++;
                    }
                }
            } else {
                unescaped_str[j++] = str[i];
            }
        }
        unescaped_str[j] = '\0';
        printf("%s\n", unescaped_str);
        free(unescaped_str);
    } else {
        printf("INVALID_MODE\n");
    }

    return 0;
}
